+/**
+ * Variance per item between two days (inclusive): theoretical use from sales
+ * sold in those days, actual use from every consume movement, and the
+ * difference (actual - theoretical). Items where both are zero are left out.
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (at) => {
+    const day = at.slice(0, 10);
+    return day >= from && day <= to;
+  };
+  const rows = new Map();
+  const row = (itemId) => {
+    if (!rows.has(itemId)) rows.set(itemId, { theoretical: 0, actual: 0 });
+    return rows.get(itemId);
+  };
+  for (const s of store.data.sales ?? []) {
+    if (!inRange(s.soldAt)) continue;
+    for (const u of s.uses) row(u.itemId).theoretical += u.qty;
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at)) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) row(batch.itemId).actual += m.qty;
+  }
+  const r3 = (n) => Math.round(n * 1000) / 1000;
+  return [...rows]
+    .map(([itemId, v]) => {
+      const item = store.data.items.find((i) => i.id === itemId);
+      const theoretical = r3(v.theoretical);
+      const actual = r3(v.actual);
+      return { itemId, name: item?.name ?? null, unit: item?.unit ?? null, theoretical, actual, difference: r3(actual - theoretical) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId);
+}
