@@ -0,0 +1,52 @@
+// Sales from the till: each dish sold uses one portion of its recipe per
+// unit of `qty`. Recording a set of sales is all or nothing.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when a sale with this ticket was recorded before. */
+export function ticketImported(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/** Ingredient use for `qty` of a dish, or AppError not_found when the dish or recipe is missing. */
+export function dishUse(store, dishId, qty) {
+  const dish = getDish(store, dishId);
+  const recipe = getRecipe(store, dish.recipeId);
+  return scaled(recipe, qty).filter((n) => n.qty > 0);
+}
+
+/**
+ * Records sales [{ row, ticket, soldAt, dishId, qty }] and consumes their
+ * ingredients (ref `sale:<ticket>`). Checks all stock first; throws
+ * sale_out_of_stock naming the row and changes nothing when an item runs out.
+ */
+export function recordSales(store, sales) {
+  const planned = sales.map((s) => ({ ...s, uses: dishUse(store, s.dishId, s.qty) }));
+  const left = new Map();
+  for (const p of planned) {
+    for (const u of p.uses) {
+      const item = getItem(store, u.itemId);
+      const available = left.has(u.itemId) ? left.get(u.itemId) : round3(onHand(store, u.itemId));
+      if (available < u.qty)
+        throw new AppError("sale_out_of_stock", { row: p.row, item: item.name, available, unit: item.unit });
+      left.set(u.itemId, round3(available - u.qty));
+    }
+  }
+  const before = structuredClone(store.data);
+  try {
+    store.data.sales ??= [];
+    for (const p of planned) {
+      for (const u of p.uses) consume(store, u.itemId, u.qty, { at: p.soldAt, ref: `sale:${p.ticket}` });
+      store.data.sales.push({ id: store.nextId("sale"), ticket: p.ticket, soldAt: p.soldAt, dishId: p.dishId, qty: p.qty, uses: p.uses });
+    }
+  } catch (e) {
+    store.data = before;
+    throw e;
+  }
+  return { tickets: new Set(planned.map((p) => p.ticket)).size, dishes: planned.reduce((n, p) => n + p.qty, 0) };
+}
